import * as Vitest from 'vitest';

export * from 'vitest';

type Hook = (fn: (...args: any[]) => any, timeout?: number) => void;

function isDoneCallback(fn: (...args: any[]) => any): boolean {
  if (fn.length === 0) {
    return false;
  }

  const source = Function.prototype.toString.call(fn).trim();
  const firstParameter = source
    .replace(/^async\s+/, '')
    .replace(/^function(?:\s+\w+)?\s*/, '')
    .match(/^\(?\s*([^,)]+)/)?.[1]
    ?.trim();

  return firstParameter !== undefined && !firstParameter.startsWith('{');
}

function wrapHook(hook: Hook): Hook {
  return function wrappedHook(fn, timeout) {
    if (!isDoneCallback(fn)) {
      return hook(fn, timeout);
    }

    return hook(() => {
      return new Promise<void>((resolve, reject) => {
        let finished = false;
        const done = (error?: unknown) => {
          if (finished) {
            return;
          }

          finished = true;
          error ? reject(error) : resolve();
        };

        try {
          const result = fn(done);
          if (result !== undefined) {
            Promise.resolve(result).then(() => done(), done);
          }
        } catch (error) {
          done(error);
        }
      });
    }, timeout);
  };
}

